-- Wave 13 D1 — 0001_canonical_and_workspaces.sql
-- Deterministic SQLite / Cloudflare D1 DDL for all 16 tables in db/schema.ts:
-- the 14 canonical tables plus workspaces + workspaceMembers (W13-D1).
-- Generated by hand from db/schema.ts (no drizzle-kit in this sandbox);
-- verify with `wrangler d1 migrations apply --local` before any remote apply (W13-D4).
-- Idempotent: every statement uses IF NOT EXISTS.

CREATE TABLE IF NOT EXISTS `business_functions` (
  `function_id` TEXT PRIMARY KEY NOT NULL,
  `name` TEXT NOT NULL,
  `status` TEXT NOT NULL DEFAULT 'Active',
  `default_currency` TEXT NOT NULL DEFAULT 'USD',
  `fiscal_year_start_month` INTEGER NOT NULL DEFAULT 6,
  `workspace_id` TEXT NOT NULL DEFAULT 'ws-local-default',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `projects` (
  `record_id` TEXT PRIMARY KEY NOT NULL,
  `project_id` TEXT NOT NULL,
  `function_id` TEXT NOT NULL REFERENCES `business_functions`(`function_id`),
  `name` TEXT NOT NULL,
  `purpose` TEXT NOT NULL DEFAULT '',
  `description` TEXT NOT NULL DEFAULT '',
  `period` TEXT NOT NULL DEFAULT 'FY27',
  `owner` TEXT NOT NULL DEFAULT '',
  `status` TEXT NOT NULL DEFAULT 'Active',
  `currency` TEXT NOT NULL DEFAULT 'USD',
  `approved_amount` REAL NOT NULL DEFAULT 0,
  `workspace_id` TEXT NOT NULL DEFAULT 'ws-local-default',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `work_packages` (
  `work_package_id` TEXT PRIMARY KEY NOT NULL,
  `project_record_id` TEXT NOT NULL REFERENCES `projects`(`record_id`),
  `name` TEXT NOT NULL DEFAULT 'General',
  `description` TEXT NOT NULL DEFAULT '',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `budget_versions` (
  `version_id` TEXT PRIMARY KEY NOT NULL,
  `project_record_id` TEXT NOT NULL REFERENCES `projects`(`record_id`),
  `sequence` INTEGER NOT NULL,
  `version_type` TEXT NOT NULL DEFAULT 'Original',
  `authorization_state` TEXT NOT NULL DEFAULT 'Proposed',
  `predecessor_id` TEXT,
  `reason` TEXT NOT NULL DEFAULT '',
  `total` REAL NOT NULL DEFAULT 0,
  `currency` TEXT NOT NULL DEFAULT 'USD',
  `snapshot_json` TEXT NOT NULL DEFAULT '[]',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `purchase_items` (
  `spending_line_id` TEXT PRIMARY KEY NOT NULL,
  `project_record_id` TEXT NOT NULL REFERENCES `projects`(`record_id`),
  `work_package_id` TEXT NOT NULL REFERENCES `work_packages`(`work_package_id`),
  `spending_item_definition_id` TEXT NOT NULL DEFAULT '',
  `description` TEXT NOT NULL,
  `specification` TEXT NOT NULL DEFAULT '',
  `unit_of_measure` TEXT NOT NULL DEFAULT 'unit',
  `quantity` REAL NOT NULL DEFAULT 0,
  `unit_price` REAL NOT NULL DEFAULT 0,
  `currency` TEXT NOT NULL DEFAULT 'USD',
  `quarters_json` TEXT NOT NULL DEFAULT '[]',
  `gl_code` TEXT NOT NULL DEFAULT '',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `sourcing_allocations` (
  `allocation_id` TEXT PRIMARY KEY NOT NULL,
  `spending_line_id` TEXT NOT NULL REFERENCES `purchase_items`(`spending_line_id`),
  `source_type` TEXT NOT NULL DEFAULT 'External vendor',
  `vendor_or_warehouse` TEXT NOT NULL DEFAULT '',
  `source_country` TEXT NOT NULL DEFAULT '',
  `source_location` TEXT NOT NULL DEFAULT '',
  `quantity` REAL NOT NULL DEFAULT 0,
  `unit_price` REAL NOT NULL DEFAULT 0,
  `additional_cost_estimate` REAL NOT NULL DEFAULT 0,
  `currency` TEXT NOT NULL DEFAULT 'USD',
  `quarter` TEXT NOT NULL DEFAULT 'Q1',
  `finance_mapping_status` TEXT NOT NULL DEFAULT 'Needs Finance review',
  `confirmed_finance_code` TEXT NOT NULL DEFAULT '',
  `notes` TEXT NOT NULL DEFAULT '',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `lifecycle_records` (
  `document_id` TEXT PRIMARY KEY NOT NULL,
  `project_record_id` TEXT NOT NULL REFERENCES `projects`(`record_id`),
  `type` TEXT NOT NULL,
  `reference` TEXT NOT NULL DEFAULT '',
  `vendor` TEXT NOT NULL DEFAULT '',
  `date` TEXT NOT NULL DEFAULT '',
  `status` TEXT NOT NULL DEFAULT 'Draft',
  `currency` TEXT NOT NULL DEFAULT 'USD',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `lifecycle_lines` (
  `document_line_id` TEXT PRIMARY KEY NOT NULL,
  `document_id` TEXT NOT NULL REFERENCES `lifecycle_records`(`document_id`),
  `project_record_id` TEXT NOT NULL REFERENCES `projects`(`record_id`),
  `spending_line_id` TEXT,
  `allocation_id` TEXT,
  `description` TEXT NOT NULL DEFAULT '',
  `quantity` REAL NOT NULL DEFAULT 0,
  `amount` REAL NOT NULL DEFAULT 0,
  `currency` TEXT NOT NULL DEFAULT 'USD',
  `spend_quarter` TEXT NOT NULL DEFAULT 'Q1',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `purchase_links` (
  `purchase_link_id` TEXT PRIMARY KEY NOT NULL,
  `document_line_id` TEXT NOT NULL REFERENCES `lifecycle_lines`(`document_line_id`),
  `spending_line_id` TEXT NOT NULL REFERENCES `purchase_items`(`spending_line_id`),
  `allocation_id` TEXT,
  `attributed_quantity` REAL NOT NULL DEFAULT 0,
  `attributed_amount` REAL NOT NULL DEFAULT 0,
  `currency` TEXT NOT NULL DEFAULT 'USD',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `lifecycle_transitions` (
  `transition_id` TEXT PRIMARY KEY NOT NULL,
  `from_line_id` TEXT NOT NULL REFERENCES `lifecycle_lines`(`document_line_id`),
  `to_line_id` TEXT NOT NULL REFERENCES `lifecycle_lines`(`document_line_id`),
  `transition_type` TEXT NOT NULL,
  `converted_amount` REAL NOT NULL DEFAULT 0,
  `currency` TEXT NOT NULL DEFAULT 'USD',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `knowledge_notes` (
  `note_id` TEXT PRIMARY KEY NOT NULL,
  `project_record_id` TEXT NOT NULL REFERENCES `projects`(`record_id`),
  `title` TEXT NOT NULL,
  `content` TEXT NOT NULL DEFAULT '',
  `attached_to_type` TEXT NOT NULL DEFAULT 'Project',
  `attached_to_id` TEXT NOT NULL,
  `wikilinks_json` TEXT NOT NULL DEFAULT '[]',
  `tags_json` TEXT NOT NULL DEFAULT '[]',
  `updated_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `audit_events` (
  `audit_id` TEXT PRIMARY KEY NOT NULL,
  `project_record_id` TEXT NOT NULL REFERENCES `projects`(`record_id`),
  `actor` TEXT NOT NULL,
  `timestamp` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `action` TEXT NOT NULL,
  `target_id` TEXT NOT NULL DEFAULT '',
  `before_delta_json` TEXT NOT NULL DEFAULT '{}',
  `after_delta_json` TEXT NOT NULL DEFAULT '{}',
  `reason` TEXT NOT NULL DEFAULT '',
  `source_ref` TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS `outcome_definitions` (
  `outcome_id` TEXT PRIMARY KEY NOT NULL,
  `function_id` TEXT REFERENCES `business_functions`(`function_id`),
  `name` TEXT NOT NULL,
  `definition` TEXT NOT NULL DEFAULT '',
  `unit` TEXT NOT NULL DEFAULT '',
  `measurement_window` TEXT NOT NULL DEFAULT '',
  `direction` TEXT NOT NULL DEFAULT 'Increase',
  `expected_evidence_source` TEXT NOT NULL DEFAULT '',
  `scope` TEXT NOT NULL DEFAULT 'Reusable',
  `lifecycle` TEXT NOT NULL DEFAULT 'Active',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `project_outcomes` (
  `project_outcome_id` TEXT PRIMARY KEY NOT NULL,
  `project_record_id` TEXT NOT NULL REFERENCES `projects`(`record_id`),
  `outcome_id` TEXT REFERENCES `outcome_definitions`(`outcome_id`),
  `name` TEXT NOT NULL,
  `baseline` TEXT NOT NULL DEFAULT '',
  `target` TEXT NOT NULL DEFAULT '',
  `current_progress` TEXT NOT NULL DEFAULT '',
  `evidence_strength` TEXT NOT NULL DEFAULT 'Moderate',
  `evidence_source` TEXT NOT NULL DEFAULT '',
  `owner` TEXT NOT NULL DEFAULT '',
  `measurement_window` TEXT NOT NULL DEFAULT '',
  `updated_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `workspaces` (
  `workspace_id` TEXT PRIMARY KEY NOT NULL,
  `name` TEXT NOT NULL,
  `slug` TEXT NOT NULL,
  `plan_tier` TEXT NOT NULL DEFAULT 'local-hybrid',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `workspace_members` (
  `member_id` TEXT PRIMARY KEY NOT NULL,
  `workspace_id` TEXT NOT NULL REFERENCES `workspaces`(`workspace_id`),
  `actor_email` TEXT NOT NULL,
  `role` TEXT NOT NULL DEFAULT 'editor',
  `token_hash` TEXT NOT NULL DEFAULT '',
  `created_at` TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Tenant-scoped project lookups (W13-D2 GET/POST filter by workspace_id).
CREATE INDEX IF NOT EXISTS `projects_workspace_id_record_id_idx` ON `projects` (`workspace_id`, `record_id`);
